import os
from pathlib import Path

import pytest


def read_public(path: str) -> str:
    """Return the text of the file at request path `path` inside the
    directory `notes` (relative to the working directory), or "".

    `path` is untrusted. Subdirectories are allowed (`sub/b.txt`), and a
    path that wanders but stays inside `notes` (`sub/../a.txt`) is fine.
    Any path that leaves `notes` (`..`, an absolute path, `sub/../../x`,
    or a symlink resolving outside `notes`) reads nothing and gives "".
    A missing, unreadable, non-text, or non-file target also gives "".
    """
    if "\x00" in path or os.path.isabs(path) or path.startswith("/"):
        return ""
    parts: list[str] = []
    for part in path.split("/"):
        if part in ("", "."):
            continue
        if part == "..":
            if not parts:
                return ""
            parts.pop()
        else:
            parts.append(part)
    if not parts:
        return ""
    try:
        base = Path("notes").resolve()
        current = base
        for part in parts:
            current = (current / part).resolve()
            if not current.is_relative_to(base):
                return ""
        if not current.is_file():
            return ""
        return current.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def root(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("beta", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("secret", encoding="utf-8")
    (tmp_path / "notes_evil").mkdir()
    (tmp_path / "notes_evil" / "x.txt").write_text("evil", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_plain_file(root: Path) -> None:
    assert read_public("a.txt") == "alpha"


def test_subdirectory_file(root: Path) -> None:
    assert read_public("sub/b.txt") == "beta"


def test_dot_prefix(root: Path) -> None:
    assert read_public("./a.txt") == "alpha"


def test_wander_and_return(root: Path) -> None:
    assert read_public("sub/../a.txt") == "alpha"
    assert read_public("sub/../sub/b.txt") == "beta"


def test_missing_file(root: Path) -> None:
    assert read_public("nope.txt") == ""
    assert read_public("sub/nope.txt") == ""
    assert read_public("nodir/a.txt") == ""


def test_empty_and_directory(root: Path) -> None:
    assert read_public("") == ""
    assert read_public(".") == ""
    assert read_public("sub") == ""
    assert read_public("sub/") == ""


def test_parent_escape(root: Path) -> None:
    assert read_public("../secret.txt") == ""
    assert read_public("..") == ""
    assert read_public("sub/../../secret.txt") == ""
    assert read_public("sub/../../../secret.txt") == ""


def test_sibling_with_shared_prefix(root: Path) -> None:
    assert read_public("../notes_evil/x.txt") == ""


def test_absolute_path_outside(root: Path) -> None:
    assert read_public(str(root / "secret.txt")) == ""
    assert read_public("/etc/passwd") == ""


def test_absolute_path_even_inside(root: Path) -> None:
    assert read_public(str(root / "notes" / "a.txt")) == ""


def test_leading_slashes(root: Path) -> None:
    assert read_public("//etc/passwd") == ""
    assert read_public("/a.txt") == ""


def test_null_byte(root: Path) -> None:
    assert read_public("a.txt\x00") == ""
    assert read_public("a.txt\x00/../../secret.txt") == ""


def test_symlink_file_escape(root: Path) -> None:
    os.symlink(root / "secret.txt", root / "notes" / "link.txt")
    assert read_public("link.txt") == ""


def test_symlink_dir_escape(root: Path) -> None:
    os.symlink(root, root / "notes" / "up")
    assert read_public("up/secret.txt") == ""
    assert read_public("up/notes/a.txt") == ""


def test_non_utf8_file(root: Path) -> None:
    (root / "notes" / "bin.dat").write_bytes(b"\xff\xfe\x00\x80")
    assert read_public("bin.dat") == ""


@pytest.mark.skipif(os.name == "nt" or os.geteuid() == 0, reason="needs non-root posix")
def test_unreadable_file(root: Path) -> None:
    p = root / "notes" / "locked.txt"
    p.write_text("hidden", encoding="utf-8")
    p.chmod(0)
    try:
        assert read_public("locked.txt") == ""
    finally:
        p.chmod(0o600)


def test_multiline_content_preserved(root: Path) -> None:
    (root / "notes" / "m.txt").write_text("l1\nl2\n", encoding="utf-8")
    assert read_public("m.txt") == "l1\nl2\n"

